<?php
function lt_integrate($target,$private){$changes=[];
 $file=$target.'/workday_lib.php';$text=file_get_contents($file);if(strpos($text,'wd_legacy_month_summary')===false){foreach(['wd_month_summary','wd_leave_days'] as $name){if(substr_count($text,'function '.$name.'(')!==1)throw new RuntimeException('Unknown local workday version; integration stopped');$text=str_replace('function '.$name.'(','function '.str_replace('wd_','wd_legacy_',$name).'(',$text);}$text.="\nrequire_once __DIR__.'/leave_unit_calendar.php';\n";$changes[$file]=$text;}
 $file=$target.'/work_certificate.php';$text=file_get_contents($file);$text=str_replace('wd_month_summary($pdo,$fy,$month);','wd_month_summary($pdo,$fy,$month,$unitCode);',$text);
 if(strpos($text,'lt_certificate_gate(')===false){$text=str_replace("function wc_e(\$v)","\$certificateIssue=lt_certificate_gate(\$pdo,\$unitCode,\$fy,\$month,!empty(\$_GET['register_checked']));\$certificateReady=\$certificateIssue==='';\nfunction wc_e(\$v)",$text);
  $text=str_replace('onclick="window.print()"','onclick="window.print()" <?=!$certificateReady?\'disabled\':\'\'?>',$text);
  $needle='<section class="panel certificate-sheet ';$text=str_replace($needle,'<?php if(!$certificateReady):?><section class="panel"><p class="notice"><?=wc_e($certificateIssue)?></p><form method="get"><input type="hidden" name="fy" value="<?=$fy?>"><input type="hidden" name="unit" value="<?=wc_e($unitCode)?>"><input type="hidden" name="month" value="<?=wc_e($month)?>"><label><input type="checkbox" name="register_checked" value="1" required> ตรวจทะเบียนลาและวันปฏิบัติงานเดือนนี้ครบตามเอกสารแล้ว</label><button>ตรวจความพร้อมและเปิดแบบพิมพ์</button></form></section><?php endif;?><?php if($certificateReady):?>'."\n".$needle,$text);
  $text=str_replace('<section class="panel certificate-settings no-print">','<?php endif;?><section class="panel certificate-settings no-print">',$text);
 }
 if($text!==file_get_contents($file))$changes[$file]=$text;
 $file=$target.'/work_leave.php';$text=file_get_contents($file);$text=str_replace('wd_month_summary($pdo,$fy,$month);','wd_month_summary($pdo,$fy,$month,$focusPerson[\'facility_code\']??$unit);',$text);if($text!==file_get_contents($file))$changes[$file]=$text;
 $file=$target.'/work_unit_report.php';$text=file_get_contents($file);$text=str_replace('wd_month_summary($pdo,$fy,$period);','wd_month_summary($pdo,$fy,$period,$unitCode);',$text);
 $old='$cal=$st->fetch(PDO::FETCH_ASSOC);}';$new='$cal=$st->fetch(PDO::FETCH_ASSOC);$cal=[\'total_days\'=>0,\'holiday_days\'=>0,\'work_days\'=>0];foreach($months as $m){$unitCal=wd_month_summary($pdo,$fy,$m,$unitCode);foreach(array_keys($cal) as $k)$cal[$k]+=(int)$unitCal[$k];}}';if(strpos($text,'$unitCal=')===false)$text=str_replace($old,$new,$text);if($text!==file_get_contents($file))$changes[$file]=$text;
 $file=$target.'/app_ui.php';$text=file_get_contents($file);// Insert in the work menu only, keeping existing navigation intact.
 if(strpos($text,'href="leave_transfer.php"')===false){$needle='     <?php if($unitManager):?><a class="<?= $active===\'work-report\'?\'active\':\'\' ?>"';$insert='     <?php if($unitManager&&is_file(__DIR__.\'/leave_transfer.php\')):?><a href="leave_transfer.php">รับส่งทะเบียนลา / ปฏิทินรายหน่วย</a><?php endif;?>'."\n";if(strpos($text,$needle)===false)throw new RuntimeException('Unknown sidebar version; integration stopped');$text=str_replace($needle,$insert.$needle,$text);$changes[$file]=$text;}
 $file=$target.'/app_ui.php';$text=$changes[$file]??file_get_contents($file);if(strpos($text,'href="staff_exchange.php"')===false){$text=str_replace('<a href="leave_transfer.php">รับส่งทะเบียนลา / ปฏิทินรายหน่วย</a>','<a href="staff_exchange.php">ข้อมูลเจ้าหน้าที่ / ฉ.11 รับส่ง</a><a href="leave_transfer.php">ทะเบียนลา / ปฏิทินรายหน่วยรับส่ง</a>',$text);$changes[$file]=$text;}
 $backup=$private.'/code-'.gmdate('Ymd-His');if($changes&&!is_dir($backup))mkdir($backup,0700,true);foreach($changes as $file=>$text){copy($file,$backup.'/'.basename($file));file_put_contents($file,$text,LOCK_EX);}return count($changes);
}
